import os
from datetime import datetime, timedelta, timezone
import boto3
from botocore.exceptions import ClientError


def query_metrics_by_dimension(instance_id: str, region: str = "us-east-1") -> list[dict]:
    client = boto3.client("cloudwatch", region_name=region)

    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(hours=1)

    try:
        response = client.get_metric_data(
            MetricDataQueries=[
                {
                    "Id": "cpu_query",
                    "MetricStat": {
                        "Metric": {
                            "Namespace": "AWS/EC2",
                            "MetricName": "CPUUtilization",
                            "Dimensions": [
                                {"Name": "InstanceId", "Value": instance_id}
                            ]
                        },
                        "Period": 300,
                        "Stat": "Average",
                        "Unit": "Percent"
                    },
                    "ReturnData": True
                }
            ],
            StartTime=start_time,
            EndTime=end_time,
            ScanBy="TimestampAscending"
        )
    except ClientError as e:
        raise RuntimeError(f"Failed to query CloudWatch metrics: {e}")

    results = []
    for metric_result in response.get("MetricDataResults", []):
        label = metric_result.get("Label")
        timestamps = metric_result.get("Timestamps", [])
        values = metric_result.get("Values", [])

        for ts, val in zip(timestamps, values):
            results.append({
                "metric": label or metric_result.get("Id"),
                "timestamp": ts.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "value": val,
                "dimensions": {"InstanceId": instance_id}
            })

    return results
